//! `config/launch.json` (generated by tools/launch-config) as the arguments of `create_market` and `create_ruleset`, and the
//! evaluator / verifier views of the same markets. Every integer in the file is a decimal string.
use std::str::FromStr;

use evaluator::{MarketCfg, RulesCfg, STATUS_ENABLED};
use serde_json::Value;
use setl8_lev_trading::{
    instructions::{CreateMarketArgs, MarketParams, RuleSetArgs},
    state::Session,
};

/// The mock price source (`PriceProof.source` 255): accepted by the `localnet` build only (decision 46).
pub const SOURCE_MOCK: u8 = 255;

pub struct Entry {
    pub args: CreateMarketArgs,
    pub symbol: String,
    /// The source the market's real feed uses (2, 3 or 4); the rehearsal feeds mock proofs (255) with the same feed id.
    pub source: u8,
}

pub struct Launch {
    pub markets: Vec<Entry>,
    pub ruleset: RuleSetArgs,
}

fn num<T: FromStr>(v: &Value) -> Result<T, String>
where
    T::Err: std::fmt::Debug,
{
    v.as_str().ok_or_else(|| format!("{v} is not a decimal string"))?.parse().map_err(|e| format!("{v}: {e:?}"))
}

fn arr<T: FromStr + Copy + Default, const N: usize>(v: &Value) -> Result<[T; N], String>
where
    T::Err: std::fmt::Debug,
{
    let a = v.as_array().ok_or("not an array")?;
    if a.len() != N {
        return Err(format!("expected {N} entries, found {}", a.len()));
    }
    let mut out = [T::default(); N];
    for (o, x) in out.iter_mut().zip(a) {
        *o = num(x)?;
    }
    Ok(out)
}

fn hex32(s: &str) -> Result<[u8; 32], String> {
    if s.len() != 64 {
        return Err(format!("feed id of {} characters", s.len()));
    }
    let mut out = [0u8; 32];
    for (k, b) in out.iter_mut().enumerate() {
        *b = u8::from_str_radix(&s[2 * k..2 * k + 2], 16).map_err(|e| e.to_string())?;
    }
    Ok(out)
}

pub fn parse(text: &str) -> Result<Launch, String> {
    let v: Value = serde_json::from_str(text).map_err(|e| format!("launch.json is not JSON: {e}"))?;
    if (v["format"].as_str(), v["version"].as_str()) != (Some("setl8-launch"), Some("1")) {
        return Err("not a setl8-launch version 1 file".into());
    }
    let mut markets = Vec::new();
    for m in v["markets"].as_array().ok_or("no markets")? {
        let p = &m["params"];
        let mut sessions = [Session::default(); 6];
        for (slot, w) in sessions.iter_mut().zip(p["sessions"].as_array().ok_or("sessions")?) {
            *slot = Session { start_min: num(&w[0])?, end_min: num(&w[1])? };
        }
        markets.push(Entry {
            args: CreateMarketArgs {
                market_id: num(&m["market_id"])?,
                class: num(&m["class"])?,
                params: MarketParams {
                    status: num(&p["status"])?,
                    feed_id: hex32(p["feed_id"].as_str().ok_or("feed_id")?)?,
                    max_age_secs: num(&p["max_age_secs"])?,
                    qty_step: num(&p["qty_step"])?,
                    qty_min: num(&p["qty_min"])?,
                    max_notional_usd: num(&p["max_notional_usd"])?,
                    session_count: num(&p["session_count"])?,
                    sessions,
                    quote_conv_market: num(&p["quote_conv_market"])?,
                },
            },
            symbol: m["meta"]["symbol"].as_str().ok_or("symbol")?.to_string(),
            source: num(&m["meta"]["source"])?,
        });
    }
    let r = &v["ruleset"];
    let ruleset = RuleSetArgs {
        version: num(&r["version"])?,
        fee_bps: num(&r["fee_bps"])?,
        tier_count: num(&r["tier_count"])?,
        ladder_len: num(&r["ladder_len"])?,
        leverage_x: arr(&r["leverage_x"])?,
        holding_fee_e6: arr(&r["holding_fee_e6"])?,
        commission_e6: arr(&r["commission_e6"])?,
        tier_size: arr(&r["tier_size"])?,
        tier_cost: arr(&r["tier_cost"])?,
        reset_ladder_bps: arr(&r["reset_ladder_bps"])?,
        spread_e6: arr(&r["spread_e6"])?,
    };
    Ok(Launch { markets, ruleset })
}

impl Launch {
    /// `(size, cost)` of the rule set's tiers, in order.
    pub fn tiers(&self) -> Vec<(u64, u64)> {
        let n = usize::from(self.ruleset.tier_count);
        (0..n).map(|i| (self.ruleset.tier_size[i], self.ruleset.tier_cost[i])).collect()
    }

    pub fn ladder(&self) -> Vec<u16> {
        self.ruleset.reset_ladder_bps[..usize::from(self.ruleset.ladder_len)].to_vec()
    }

    /// The evaluator's view of the markets: the launch parameters. With `mock` the proofs are mock proofs (source 255, accepted by the
    /// `localnet` build only) carrying each market's own feed id; without it they use the market's real source format (2, 3 or 4:
    /// the program checks only their shape, the public verifier checks them against the archive).
    pub fn rules_cfg(&self, mock: bool) -> RulesCfg {
        let markets = self
            .markets
            .iter()
            .map(|m| MarketCfg {
                id: m.args.market_id,
                class: m.args.class,
                source: if mock { SOURCE_MOCK } else { m.source },
                feed_id: m.args.params.feed_id,
                max_age_secs: m.args.params.max_age_secs,
                status: STATUS_ENABLED,
                qty_step: m.args.params.qty_step,
                qty_min: m.args.params.qty_min,
                max_notional_micro: m.args.params.max_notional_usd,
                sessions: m.args.params.sessions[..usize::from(m.args.params.session_count)].iter().map(|s| (s.start_min, s.end_min)).collect(),
                half_spread_e6: u32::from(self.ruleset.spread_e6[usize::from(m.args.market_id)]),
            })
            .collect();
        RulesCfg {
            ruleset_version: self.ruleset.version,
            leverage_x: self.ruleset.leverage_x,
            holding_fee_e6: self.ruleset.holding_fee_e6,
            commission_e6: self.ruleset.commission_e6,
            markets,
        }
    }

    pub fn symbol_index(&self, symbol: &str) -> Option<u16> {
        self.markets.iter().find(|m| m.symbol == symbol).map(|m| m.args.market_id)
    }
}

/// The verifier's `rules.json` from the chain's own accounts (a watchdog reads the same): the rule set, then every market.
pub fn rules_json(rs: &setl8_lev_trading::state::RuleSet, markets: &[setl8_lev_trading::state::Market]) -> String {
    let ms: Vec<Value> = markets
        .iter()
        .map(|m| {
            serde_json::json!({
                "id": m.market_id, "class": m.class, "feed_id": setl8_verify::hexutil::encode(&m.feed_id), "max_age_secs": m.max_age_secs,
                "status": m.status, "qty_step": m.qty_step, "qty_min": m.qty_min, "max_notional_usd": m.max_notional_usd,
                "sessions": m.sessions[..usize::from(m.session_count)].iter().map(|s| serde_json::json!([s.start_min, s.end_min])).collect::<Vec<_>>()
            })
        })
        .collect();
    let spread: serde_json::Map<String, Value> = markets.iter().map(|m| (m.market_id.to_string(), serde_json::json!(rs.spread_e6[usize::from(m.market_id)]))).collect();
    serde_json::json!({
        "version": 1, "ruleset_version": rs.version, "fee_bps": rs.fee_bps, "leverage_x": rs.leverage_x, "holding_fee_e6": rs.holding_fee_e6,
        "commission_e6": rs.commission_e6, "tier_sizes": &rs.tier_size[..usize::from(rs.tier_count)], "spread_e6": spread, "markets": ms
    })
    .to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn real() -> Launch {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../config/launch.json");
        parse(&std::fs::read_to_string(&path).expect("config/launch.json")).expect("launch.json parses")
    }

    #[test]
    fn the_real_launch_file_has_21_markets_ten_unique_tiers_and_the_decision_17_ladder() {
        let l = real();
        assert_eq!(l.markets.len(), 21);
        for (k, m) in l.markets.iter().enumerate() {
            assert_eq!(usize::from(m.args.market_id), k, "ids are sequential");
        }
        let tiers = l.tiers();
        assert_eq!(tiers.len(), 10);
        let mut sizes: Vec<u64> = tiers.iter().map(|t| t.0).collect();
        sizes.dedup();
        assert_eq!(sizes.len(), 10, "ten unique sizes (the vault refuses a repeated one, DuplicateChallengeSize 6044)");
        assert_eq!(l.ladder(), vec![10_000, 11_500, 12_000, 12_750, 13_000]);
        assert_eq!(l.ruleset.fee_bps, 40);
        // the first markets of the rehearsal are the 24/7 crypto majors
        assert_eq!(l.symbol_index("BTC"), Some(0));
        assert_eq!(l.symbol_index("ETH"), Some(1));
        assert_eq!(l.symbol_index("SOL"), Some(2));
        for id in 0..3 {
            let p = &l.markets[id].args.params;
            assert_eq!((p.session_count, p.sessions[0].start_min, p.sessions[0].end_min), (1, 0, 10_080), "market {id} is open all week");
        }
    }

    #[test]
    fn the_evaluator_view_carries_the_launch_feed_ids_with_the_mock_source() {
        let l = real();
        let r = l.rules_cfg(true);
        assert_eq!(r.markets.len(), 21);
        assert!(r.markets.iter().all(|m| m.source == SOURCE_MOCK));
        let real = l.rules_cfg(false);
        assert_eq!(real.markets[0].source, 2, "BTC is a GMX market");
        assert_eq!(real.markets[9].source, l.markets[9].source);
        assert_eq!(r.markets[0].feed_id, l.markets[0].args.params.feed_id);
        assert_eq!(r.markets[0].half_spread_e6, u32::from(l.ruleset.spread_e6[0]));
        assert!(r.markets[0].half_spread_e6 > 0, "a priced market (decision 64)");
    }

    #[test]
    fn a_malformed_file_is_refused_with_a_reason() {
        assert!(parse("{").is_err());
        assert!(parse("{\"format\":\"other\",\"version\":\"1\"}").is_err());
        let text = std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../config/launch.json")).unwrap();
        assert!(parse(&text.replace("\"tier_count\": \"10\"", "\"tier_count\": 10")).is_err(), "integers are decimal strings");
    }
}
